int fact(int n){
    if(n==0) return 1;
    return n*fact(n-1);
}

int even(int n){
    if(n==0) return 1;
    return odd(n-1);
}
int odd(int n){
    if(n==0) return 0;
    return even(n-1);
}

int sum(int n, int acc){
    if(n==0) return acc;
    return sum(n-1, acc+n);
}

void print(int n){
    if(n==0) return;
    printf("%d ", n);
    print(n-1);
}

