#include <stdio.h>
#define MAX 5
int queue[MAX];
int front = -1;
int rear = -1;

int isFull() {
    return rear == MAX; // BUG: should be MAX-1
}

int isEmpty() {
    return front == -1 || front > rear;
}

void enqueue(int x) {
    if (isFull()) {
        printf("Overflow\n");
        return;
    }
    if (front == -1) front = 0;
    rear++;
    queue[rear] = x;
}

int dequeue() {
    if (isEmpty()) {
        printf("Underflow\n");
        return -1;
    }
    int val = queue[front];
    front++;
    if (front > rear) {
        front = rear = -1; // reset queue
    }
    return val;
}

int main() {
    enqueue(10);
    enqueue(20);
    enqueue(30);
    enqueue(40);
    enqueue(50);
    enqueue(60); // should trigger overflow
    printf("%d ", dequeue());
    printf("%d ", dequeue());
    enqueue(70);
    enqueue(80); // should trigger overflow again
    while (!isEmpty()) {
        printf("%d ", dequeue());
    }
    dequeue(); // should trigger underflow
    return 0;
}

#include <stdio.h>
#define MAX 10

int deque[MAX];
int front = -1;
int rear = -1;

int isFull() {
    return (front == 0 && rear == MAX-1) || (front == rear+1);
}

int isEmpty() {
    return front == -1;
}

void insertRear(int x) {
    if (isFull()) {
        printf("Overflow\n");
        return;
    }
    if (isEmpty()) {
        front = rear = 0;
    } else if (rear == MAX-1) {
        rear = 0;
    } else {
        rear++;
    }
    deque[rear] = x;
}

void insertFront(int x) {
    if (isFull()) {
        printf("Overflow\n");
        return;
    }
    if (isEmpty()) {
        front = rear = 0;
    } else if (front == 0) {
        front = MAX;   /* BUG: should wrap to MAX-1 */
    } else {
        front--;
    }
    deque[front] = x;
}

int deleteFront() {
    if (isEmpty()) {
        printf("Underflow\n");
        return -1;
    }
    int data = deque[front];
    if (front == rear) {
        front = rear = -1;
    } else if (front == MAX-1) {
        front = 0;
    } else {
        front++;
    }
    return data;
}

int deleteRear() {
    if (isEmpty()) {
        printf("Underflow\n");
        return -1;
    }
    int data = deque[rear];
    if (front == rear) {
        front = rear = -1;
    } else if (rear == 0) {
        rear = MAX-1;
    } else {
        rear--;
    }
    return data;
}

void display() {
    if (isEmpty()) {
        printf("Deque is empty\n");
        return;
    }
    int i = front;
    printf("Deque contents: ");
    while (1) {
        printf("%d ", deque[i]);
        if (i == rear) break;
        i = (i + 1) % MAX;
    }
    printf("\n");
}

int main() {
    insertRear(10);
    insertRear(20);
    insertFront(5);
    insertFront(2);
    display();
    deleteRear();
    deleteFront();
    display();
    return 0;
}
